process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const KAT='';
const DEP=Buffer.from('','base64').toString();
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'uxs4', content:b64}; if(sha) body.sha=sha;
  const pr=await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
  return pr.status;
}
const putJson=(p,o)=>putRaw(p, Buffer.from(JSON.stringify(o,null,2)).toString('base64'),'uxs4 json');
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await r.json();
}
async function off(id){ await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'UXS4'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await r.json();
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }

  let s=await snip('TEMP uxs4 set kat', "update_option('ps_uxd_kat','"+KAT+"','no');");
  await pause(2000); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  const sd=await snip('TEMP uxs4 deploy', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_uxd2=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  try{ out.deploy=JSON.parse(await resp.text()); }catch(e){ out.deploy_raw='nejson'; }

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e)));
  page.on('dialog',async d=>{ out.dialogas=(d.message()||'').slice(0,140); await d.dismiss(); });

  await page.goto(`${WP}/?ps_uxlog2=1&k=dq7m3z`,{waitUntil:'networkidle',timeout:60000});

  /* 1) VIRSUS: paieskos laukas — kontrasto matavimas */
  await page.goto(`${WP}/wp-admin/admin.php?page=ps-katalogas&kruva=visos&per=25`,{waitUntil:'networkidle',timeout:60000});
  await pause(1200);
  out.paieska=await page.evaluate(()=>{
    const i=document.querySelector('.pskat-search input'); if(!i) return null;
    const cs=getComputedStyle(i);
    return {fonas:cs.backgroundColor, tekstas:cs.color, placeholder:i.placeholder};
  });
  let png=await page.screenshot({clip:{x:0,y:60,width:1680,height:220}});
  out.s_virsus=await putRaw('screenshots/uxs4_virsus.png', png.toString('base64'),'uxs4 virsus');

  /* 2) KORTELE: purvinas laukas + sargas + kopijavimas + uzuomina + truksta */
  await page.goto(`${WP}/wp-admin/admin.php?page=ps-katalogas&kruva=visos&q=EU221Y`,{waitUntil:'networkidle',timeout:60000});
  await pause(1200);
  const a=await page.$('.pskat-t tbody tr[data-id] a.atv');
  if(a){ await a.click(); await pause(3500);
    out.uzuomina=await page.evaluate(()=>{ const u=document.querySelector('.kort-uzuomina'); return u?u.textContent.trim():null; });
    out.kopij_yra=await page.evaluate(()=>document.querySelectorAll('.kort-kopij').length);
    out.truksta_akcentas=await page.evaluate(()=>{
      const t=document.querySelector('.kort-desine .truksta, .kort-pane .truksta');
      return t?t.textContent.trim().slice(0,90):null;
    });
    /* pakeiciam kaina BE Enter → laukas turi tapti geltonas */
    await page.evaluate(()=>{
      const i=document.querySelector('.kort-kaina input');
      if(i){ i.focus(); i.value='9.99'; i.dispatchEvent(new Event('input',{bubbles:true})); }
    });
    await pause(400);
    out.purvinas=await page.evaluate(()=>{
      const i=document.querySelector('.kort-kaina input');
      return i?{klase:i.className, fonas:getComputedStyle(i).backgroundColor}:null;
    });
    png=await page.screenshot();
    out.s_kort=await putRaw('screenshots/uxs4_kortele.png', png.toString('base64'),'uxs4 kort');
    /* bandom uzdaryti su purvinu lauku → turi klausti (dialog dismiss = liekam) */
    await page.click('.kort-x');
    await pause(700);
    out.kortele_liko_atvira=await page.evaluate(()=>{ const k=document.getElementById('pskat-kort'); return !!k && !k.hidden; });
    /* Esc atstato → geltona dingsta, tada uzdarom be klausimo */
    await page.evaluate(()=>{
      const i=document.querySelector('.kort-kaina input');
      if(i){ i.value=i.dataset.buvo||''; i.classList.remove('purvinas'); }
    });
    out.dialogas2_neturi_buti=null;
    await page.click('.kort-x'); await pause(500);
    out.kortele_uzdaryta_svariam=await page.evaluate(()=>{ const k=document.getElementById('pskat-kort'); return !!k && k.hidden; });
  }
  out.js_klaidos=jsErr.slice(0,6);
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await r.json();
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putJson('analize/uxs4.json', out);
}
main().catch(async e=>{ await putJson('analize/uxs4.json',{klaida:String(e),stack:String(e&&e.stack).slice(0,600)}); });
